sys_script_include.script:
var ScheduleUtils = Class.create();
ScheduleUtils.prototype = {
    initialize: function() {},

    getAvailableSchedules: function() {
        var available = [];
        var userId = gs.getUserID();

        gs.info("[ScheduleUtils] Iniciando debug para o usuário: " + userId);

        // busca apenas agendas com state = 2 (open)
        var grSchedule = new GlideRecord("x_1793782_traini_0_schedule");
        grSchedule.addQuery("state", "2");
        grSchedule.query();

        while (grSchedule.next()) {
            var courseId = grSchedule.course.toString();
            var scheduleId = grSchedule.getUniqueValue();
            var scheduleNumber = grSchedule.number;
            var instructorId = (grSchedule.instructor + "") || "";

            gs.info("[ScheduleUtils] Verificando agenda: " + scheduleNumber + " (Curso: " + courseId + ")");

            // 🔸 regra 10: instrutor não pode se matricular na própria agenda
            if (instructorId && instructorId === userId) {
                gs.info("[ScheduleUtils] Usuário é o instrutor desta agenda → ignorada");
                continue;
            }

            // 🔸 regra 7: já matriculado nesta agenda (ignorando reproved)
            var grEnrollCheck = new GlideRecord("x_1793782_traini_0_enrollment");
            grEnrollCheck.addQuery("opened_by", userId);
            grEnrollCheck.addQuery("schedule", scheduleId);
            grEnrollCheck.addQuery("state", "NOT IN", "2");
            grEnrollCheck.query();
            if (grEnrollCheck.hasNext()) {
                gs.info("[ScheduleUtils] Usuário já tem matrícula ativa nesta agenda → ignorada");
                continue;
            }

            // 🔸 regra 8: no máximo 3 matrículas por curso (ignorando reproved)
            var grEnrollCount = new GlideAggregate("x_1793782_traini_0_enrollment");
            grEnrollCount.addQuery("opened_by", userId);
            grEnrollCount.addQuery("schedule.course", courseId);
            grEnrollCount.addQuery("state", "NOT IN", "2");
            grEnrollCount.addAggregate("COUNT");
            grEnrollCount.query();

            var total = 0;
            if (grEnrollCount.next())
                total = parseInt(grEnrollCount.getAggregate("COUNT"), 10);

            gs.info("[ScheduleUtils] Matrículas válidas no curso " + courseId + ": " + total);

            if (total >= 3) {
                gs.info("[ScheduleUtils] Curso já atingiu 3 matrículas válidas → ignorada");
                continue;
            }

            // ✅ se passou em tudo, adiciona
            gs.info("[ScheduleUtils] Agenda liberada: " + scheduleNumber);
            available.push(scheduleId);
        }

        gs.info("[ScheduleUtils] Agendas liberadas: " + available.join(", "));
        return available.join(",");
    },

    type: "ScheduleUtils"
};
